{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of the mission — is it to maximize the probability that at least two of the four key parts are destroyed, or is it to minimize total fuel consumption (or some other quantity) subject to the mission being successful?"
  ],
  "rationale": "The response asks for a single policy choice regarding the mission objective, presenting mutually exclusive options within one sentence."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When the aircraft carries a bomb to a target, does it drop the bomb on arrival and then return to the airport empty (so the outbound leg uses the loaded fuel efficiency and the return leg uses the empty 4 km/liter efficiency), or does it carry the bomb the entire round trip?"
  ],
  "rationale": "The response presents a single binary choice regarding the aircraft's payload status during the return leg, which constitutes one semantically independent clarification question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can the aircraft carry more than one bomb per trip (for example, multiple heavy bombs or a mix of heavy and light bombs in a single sortie), or is each trip limited to carrying exactly one bomb?"
  ],
  "rationale": "The response asks a single clarification question regarding the capacity limit per trip, presenting a binary choice between multiple bombs and exactly one bomb."
}

{
  "action": "question",
  "question_count": 1,
